import React, { useEffect, useState } from "react";

/* =========================
   型定義
========================= */
interface Ranking {
  id: number;
  workId: number;
  issueId: number;
  rank: number;
}

/* =========================
   コンポーネント
========================= */
const AdminRankingPage: React.FC = () => {
  const [rankings, setRankings] = useState<Ranking[]>([]);
  const [loading, setLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);

  /* -------------------------
     一覧取得
  -------------------------- */
  const fetchRankings = async () => {
    try {
      setLoading(true);
      const res = await fetch("/rankings");

      if (!res.ok) {
        throw new Error("取得失敗");
      }

      const data: Ranking[] = await res.json();
      setRankings(data);
    } catch (err) {
      setError("データ取得に失敗しました");
    } finally {
      setLoading(false);
    }
  };

  /* -------------------------
     更新処理
  -------------------------- */
  const handleUpdate = async (ranking: Ranking) => {
    try {
      const res = await fetch(`http://localhost:8080/admin/rankings/${ranking.issueId}`, {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          rank: ranking.rank,
          issue_id: ranking.issueId,
          work_id: ranking.workId,
        }),
      });

      if (!res.ok) {
        throw new Error("更新失敗");
      }

      alert("更新しました");
      fetchRankings(); // 再取得
    } catch (err) {
      alert("更新に失敗しました");
    }
  };

  /* -------------------------
     初期ロード
  -------------------------- */
  useEffect(() => {
    fetchRankings();
  }, []);

  /* =========================
     表示
  ========================= */
  return (
    <div style={{ padding: "20px" }}>
      <h1>順位管理（Admin）</h1>

      {loading && <p>読み込み中...</p>}
      {error && <p style={{ color: "red" }}>{error}</p>}

      {rankings.map((r) => (
        <div
          key={r.id}
          style={{
            display: "flex",
            gap: "10px",
            marginBottom: "8px",
            alignItems: "center",
          }}
        >
          <span>ID: {r.id}</span>
          <span>Issue: {r.issueId}</span>

          <input
            type="number"
            value={r.rank}
            min={1}
            onChange={(e) => {
              const newRank = Number(e.target.value);

              setRankings((prev) =>
                prev.map((item) =>
                  item.id === r.id
                    ? { ...item, rank: newRank }
                    : item
                )
              );
            }}
            style={{ width: "60px" }}
          />

          <button onClick={() => handleUpdate(r)}>
            更新
          </button>
        </div>
      ))}
    </div>
  );
};

export default AdminRankingPage;
